/**
 * Giving copy — the one module for the /donate gift form's tier sentences,
 * the greatest-need caveat, and the "Most needed right now" card.
 *
 * All wording is founder-approved verbatim (brief 2026-11-01; the needs-card
 * closing verb "include" is a founder ruling of the same date). Tier
 * sentences describe what cash purchases actually provide: new essentials,
 * never the retired school-gear and clothing-season framing. Each frequency's
 * sentence is its own stored string — never generated by appending to the
 * one-time text.
 *
 * `lead` is the dollar figure the form renders in sage; `rest` is the
 * remainder of the sentence. Rendered together they read as one sentence.
 */

export type GiftFrequency = "one-time" | "monthly";

export type GiftTierCopy = {
  /** Sage-rendered opening dollar figure, e.g. "$25". */
  lead: string;
  /** Remainder of the sentence, starting lowercase after the amount. */
  rest: string;
};

export type GiftTier = {
  amount: number;
  copy: Record<GiftFrequency, GiftTierCopy>;
};

